```java
public int calculate(int[] arr) {
    int result = 0;
    for (int i = 0; i < arr.length; i++) {
        for (int j = 0; j < arr.length; j++) {
            for (int k = 0; k < arr.length; k++) {
                if (arr[i] + arr[j] == arr[k]) {
                    result++;
                }
            }
        }
    }
    return result;
}
